# Obtener el modelo pos.order pos_order_model = env.ref('point_of_sale.model_pos_order').id # Definir las plantillas POS templates_data = [ { 'name': 'Ticket POS WhatsApp', 'body': '🧾 *Ticket de Compra*

Hola {{1}},

Gracias por tu compra en {{2}}.

📝 Pedido: {{3}}
💰 Total: {{4}}
📅 Fecha: {{5}}

¡Gracias por tu preferencia!', 'category': 'utility', 'language': 'es', 'model_id': pos_order_model, 'variables': [ {'sequence': 1, 'variable_index': 1, 'name': 'Nombre del Cliente', 'field_name': 'partner_id.name', 'demo_value': 'Sample value'}, {'sequence': 2, 'variable_index': 2, 'name': 'Nombre de la Tienda', 'field_name': 'config_id.name', 'demo_value': 'Sample value'}, {'sequence': 3, 'variable_index': 3, 'name': 'Número de Pedido', 'field_name': 'name', 'demo_value': 'Sample value'}, {'sequence': 4, 'variable_index': 4, 'name': 'Total', 'field_name': 'amount_total', 'demo_value': 'Sample value'}, {'sequence': 5, 'variable_index': 5, 'name': 'Fecha', 'field_name': 'date_order', 'demo_value': 'Sample value'}, ], 'buttons': [], }, { 'name': 'Ticket POS WhatsApp Interactivo', 'body': '¿Desea recibir su ticket de la compra realizada recientemente? Pulse el botón correspondiente.', 'category': 'utility', 'language': 'es', 'model_id': pos_order_model, 'variables': [], 'buttons': [ {'sequence': 1, 'name': 'Sí', 'button_type': 'quick_reply'}, {'sequence': 2, 'name': 'No', 'button_type': 'quick_reply'}, ], }, ] # Obtener todos los gateways de WhatsApp gateways = env['mail.gateway'].search([('gateway_type', '=', 'whatsapp')]) if not gateways: raise UserError('No se encontraron gateways de WhatsApp configurados. Por favor, configure al menos un gateway antes de cargar las plantillas.') created_count = 0 updated_count = 0 for gateway in gateways: created_templates = {} # Crear o actualizar plantillas for template_data in templates_data: existing = env['mail.whatsapp.template'].search([ ('name', '=', template_data['name']), ('gateway_id', '=', gateway.id), ('language', '=', template_data['language']), ], limit=1) template_vals = { 'name': template_data['name'], 'body': template_data['body'], 'category': template_data['category'], 'language': template_data['language'], 'model_id': template_data['model_id'], 'gateway_id': gateway.id, 'state': 'draft', } if existing: existing.write(template_vals) template = existing updated_count += 1 else: template = env['mail.whatsapp.template'].create(template_vals) created_count += 1 created_templates[template_data['name']] = template # Configurar variables y botones for template_data in templates_data: template = created_templates[template_data['name']] template.variable_ids.unlink() template.button_ids.unlink() for var_data in template_data['variables']: var_vals = { 'template_id': template.id, 'sequence': var_data['sequence'], 'variable_index': var_data['variable_index'], 'name': var_data['name'], 'field_name': var_data['field_name'], 'field_type': 'field', } if 'demo_value' in var_data: var_vals['demo_value'] = var_data['demo_value'] env['mail.whatsapp.template.variable'].create(var_vals) for button_data in template_data['buttons']: button_vals = { 'template_id': template.id, 'sequence': button_data['sequence'], 'name': button_data['name'], 'button_type': button_data['button_type'], } env['mail.whatsapp.template.button'].create(button_vals) message = 'Plantillas POS cargadas correctamente:
- Creadas: %s
- Actualizadas: %s' % (created_count, updated_count) action = { 'type': 'ir.actions.client', 'tag': 'display_notification', 'params': { 'title': 'Plantillas WhatsApp POS', 'message': message, 'type': 'success', 'sticky': False, } }
